export const FIELD_BY_ID=Object.fromEntries(DOCUMENT_FIELDS.map(f=>[f.id,f]));
export function documentValue(type,raw){
 const text=String(raw??'').trim();if(!text)return {valid:false,reason:'Brak wartości'};
 const folded=foldDocument(text);let value=text;
 if(type==='boolean'){value=({yes:'yes',tak:'yes',true:'yes',no:'no',nie:'no',false:'no'})[folded];if(!value)return {valid:false,reason:'Wybierz Tak albo Nie.'};}
 if(type==='date'){value=importDate(text.replace(/\s+(?=\d)/g,''));if(!value)return {valid:false,reason:'Sprawdź pełną datę, wraz z rokiem.'};}
 if(['money','integer','fte'].includes(type)){
  if(type==='fte'&&/^(?:pelny|caly) etat$/.test(folded))value=1;
  else if(type==='fte'&&/^\d\s*\/\s*\d$/.test(text)){const [a,b]=text.split('/').map(Number);value=a/b;}
  else{const amount=text.replace(/(?:PLN|z[lł]|g)\.?\s*$/i,'').replace(/[\s\u00a0]/g,'').replace(',','.');if(!/^\d+(?:\.\d{1,2})?$/.test(amount))return {valid:false,reason:'Nie znaleziono jednoznacznej liczby.'};value=Number(amount);}
  if(!Number.isFinite(value)||value<0||value>1e8||type==='integer'&&!Number.isInteger(value)||type==='fte'&&(value<=0||value>1))return {valid:false,reason:'Liczba wymaga sprawdzenia.'};
 }
 if(type==='occupation'){value=({employee:'employee',pracownik:'employee','umowa o prace':'employee',business:'business','dzialalnosc gospodarcza':'business',jdg:'business',contract:'contract','umowa zlecenia':'contract','umowa zlecenie':'contract',zlecenie:'contract',uninsured:'uninsured',startup:'startup',krus:'krus'})[folded];if(!value)return {valid:false,reason:'Przypisz rodzaj tytułu z listy.'};}
 if(type==='coverage'){value=({compulsory:'compulsory',obowiazkowe:'compulsory',voluntary:'voluntary',dobrowolne:'voluntary',none:'none',brak:'none','nie podlega':'none',unknown:'unknown'})[folded];if(!value)return {valid:false,reason:'Nie ustalono charakteru chorobowego.'};}
 if(type==='insuranceCode'){value=occupationFromZusCode(text);if(!value)return {valid:false,reason:'Kod tytułu wymaga ręcznego sprawdzenia.'};}
 if(type==='pesel'){value=text.replace(/\s/g,'');if(!/^\d{11}$/.test(value)||[...value].reduce((n,c,i)=>n+Number(c)*[1,3,7,9,1,3,7,9,1,3,1][i],0)%10)return {valid:false,reason:'Sprawdź cyfry numeru PESEL.'};}
 return {valid:true,value};
}
